    def __init__(self,owner,parent):
        super().__init__(parent);self.owner=owner;self.start_y=None
        self.setFixedSize(84,28);self.setCheckable(True);self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setStyleSheet('QToolButton{background:#293344;color:#e2eafb;border:1px solid #5b6c86;border-radius:6px;padding:2px;}'
            'QToolButton:hover{background:#523244;border-color:#ff8097;} '
            'QToolButton:checked{background:#723247;border-color:#ff8097;} QToolButton:disabled{color:#7b8493;border-color:#424b5d;}')
        self.clicked.connect(owner.toggle_dual_mode);self.sync()

    def sync(self):
        active=bool(self.owner.pages and self.owner.preview_dialog is not None and not self.owner.preview_dialog.closed)
        self.setEnabled(active and not self.owner.dual_anim_closing)
        self.setText('듀 □|□');self.setChecked(self.owner.dual_mode)
        tip='좌우 비교 접기' if self.owner.dual_mode else '클릭하거나 아래로 당겨 썸네일 자리에 오른쪽 비교 화면 펼치기'
        self.setToolTip(tip);self.setAccessibleName(tip);self.update()

    def place_handle(self):self.sync()

    def mousePressEvent(self,event):
        if event.button()==Qt.MouseButton.LeftButton:self.start_y=event.globalPosition().y()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self,event):
        distance=event.globalPosition().y()-self.start_y if self.start_y is not None else 0
        self.start_y=None
        if event.button()==Qt.MouseButton.LeftButton and self.isEnabled() and distance>=self.THRESHOLD:
            self.setDown(False);self.owner.toggle_dual_mode();event.accept();return
        super().mouseReleaseEvent(event)


