                handle=self.bulk_handle_at(point) if editor.bulk_items else self.vector_handle_at(point) if editor.selected_vector else self.image_handle_at(point)
                if handle is not None and editor.selected_vector and editor.selected_vector.get('shape')=='line':
                    a,b=editor.vector_target[0]['segments'][0]
                    horizontal=abs(b[0]-a[0])>=abs(b[1]-a[1])
                    cursor=Qt.CursorShape.SizeHorCursor if horizontal==(handle<2) else Qt.CursorShape.SizeVerCursor
                else:
                    cursor=({0:Qt.CursorShape.SizeFDiagCursor,2:Qt.CursorShape.SizeFDiagCursor,1:Qt.CursorShape.SizeBDiagCursor,3:Qt.CursorShape.SizeBDiagCursor,4:Qt.CursorShape.SizeVerCursor,6:Qt.CursorShape.SizeVerCursor,5:Qt.CursorShape.SizeHorCursor,7:Qt.CursorShape.SizeHorCursor}[handle]
                            if handle is not None else (Qt.CursorShape.SizeAllCursor if editor.text_move_mode or editor.movement_focus_active() or (editor.selected_image or editor.selected_vector) and self.hover else Qt.CursorShape.IBeamCursor if self.hover and 'text' in self.hover else Qt.CursorShape.ArrowCursor))
