        self.resize(1050, 880)
        if owner.single_file_layout:
            fit_document_window(self,True,owner.screen())
        self.owner = owner
        self.page = page
        self.token = 0
        self.info_token = 0
        self.edit_token = 0
        self.requested_side = 0
        self.preview_ready = False
        self.reading_base_pix=QPixmap()
        self.closed = False
        self.mode = 'pan'
        self.info = None
        self.loading_info = False
