        self.edit_source = None
        self.pending_cover = None
        self.pending_cover_path = None
        self.selected_text = None
        self.selected_image = None
        self.selected_vector=None;self.vector_target=None;self.restore_vector=None;self.after_vector=None
        self.bulk_items=[];self.bulk_offset=[0.,0.];self.bulk_targets=None;self.bulk_resize_handle=None;self.bulk_drag_start=None;self.bulk_drag_offset=[0.,0.]
        self.bulk_restore=None;self.after_bulk=None;self.pending_bundle=None;self.commit_cursor_state=None
        self.vector_drag_base=None;self.vector_drag_start=None;self.vector_drag_handle=None
        self.vector_backdrop_token=None;self.vector_backdrop_key=None;self.vector_backdrop_ready=False
        self.image_target = None
        self.image_drag_base = None
        self.restore_image = None
        self.after_image = None
