        self.eyedropper_button=QToolButton();self.eyedropper_button.setText('스포이드');self.eyedropper_button.setCheckable(True);self.eyedropper_button.clicked.connect(self.start_eyedropper)
        image_row.insertWidget(0,self.cover_color_button);image_row.insertWidget(1,self.eyedropper_button)
        self.image_panel.hide()
        self.color_preview=QLabel(self.view.viewport());self.color_preview.hide()
        self.color_preview.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.color_preview.setStyleSheet('QLabel{background:#202631;color:white;border:1px solid #8d9bac;border-radius:4px;padding:6px;}')
        self.update_cover_swatch()
        self.actions=CornerActions(self.view.viewport(),self,self.save_copy,owner.translate_current,owner.choose_hangul,lambda:owner.show_settings(self),owner.clear,print_document=owner.print_document)
        self.actions.save_button.setToolTip(owner.save_button.toolTip())
        if embedded:
            self.setWindowFlags(Qt.WindowType.Widget)
            self.setMinimumSize(200,0 if self.dual_secondary else 240)
            self.actions.hide()
